mapper.select:
SELECT mg.CORP_GR AS corp_gr , TO_CHAR(mg.TR_YMD, 'YYYY-MM-DD') AS tr_ymd , mg.TR_CD AS tr_cd , mg.FUND_CD AS fund_cd , mg.TR_CO_CD AS tr_co_cd , mg.TRUSTEE AS trustee , mg.JM_CD AS yj_cd , mg.BS_TYPE AS bs_type , mg.TR_SEQ AS tr_seq , mg.CURRENCY AS currency , mg.TR_JUSU AS tr_jusu , mg.TR_DANGA AS tr_danga , mg.TR_TAX AS tr_tax , mg.TR_COST AS tr_cost , mg.TR_AEK AS tr_aek , TO_CHAR(mg.GYULJE_YMD, 'YYYY-MM-DD') AS gyulje_ymd , mg.GYULJE_AEK AS gyulje_aek , NVL(ia.FUND_NM, F_FUND_NM(mg.CORP_GR, mg.FUND_CD)) AS fund_nm , NVL(ia.FUND_NM, F_FUND_NM(mg.CORP_GR, mg.FUND_CD)) AS xx_fund_cd , NVL(ya.JM_NM, F_JM_NM(mg.CORP_GR, mg.JM_CD)) AS jm_nm , NVL(ya.JM_NM, F_JM_NM(mg.CORP_GR, mg.JM_CD)) AS xx_yj_cd , mg.GYULJE_JM_CD AS gyulje_jm_cd , mg.COUNT_COST AS count_cost , mg.SEC_CODE AS sec_code , mg.SETT_LOCATION AS sett_location , mg.COUNT_BIC AS count_bic , mg.TRANS_RT AS trans_rt , mg.WON_GYULJE_AEK AS won_gyulje_aek , mg.WON_CHUI_AEK AS won_chui_aek , 1 AS p_visible FROM SYT0MG mg , SZM0IA ia , SYM0YA ya WHERE mg.CORP_GR = #{corpGr} AND mg.TR_YMD = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')
AND mg.TR_CD = #{trCd}
AND mg.FUND_CD = #{fundCd}
AND ia.CORP_GR(+) = mg.CORP_GR AND ia.FUND_CD(+) = mg.FUND_CD AND ya.CORP_GR(+) = mg.CORP_GR AND ya.JM_CD(+) = mg.JM_CD ORDER BY mg.FUND_CD ASC , mg.TR_SEQ ASC

SELECT NVL(MAX(TR_SEQ), 0)
  FROM SYT0MG
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')

   AND FUND_CD = #{fundCd}

SELECT CURRENCY
  FROM SYX2MM
 WHERE CORP_GR = #{corpGr}
   AND TRUSTEE = #{trustee}
   AND ROWNUM  = 1

SELECT MG_CD
  FROM SZM0IA
 WHERE CORP_GR = #{corpGr}
   AND FUND_CD = #{fundCd}
   AND ROWNUM  = 1

mapper.insert:
INSERT INTO SYT0MG (
    CORP_GR
  , TR_YMD
  , TR_CD
  , FUND_CD
  , TR_CO_CD
  , TRUSTEE
  , JM_CD
  , BS_TYPE
  , TR_SEQ
  , CURRENCY
  , TR_JUSU
  , TR_DANGA
  , TR_TAX
  , TR_COST
  , TR_AEK
  , GYULJE_YMD
  , GYULJE_AEK
  , GYULJE_JM_CD
  , COUNT_COST
  , SEC_CODE
  , SETT_LOCATION
  , COUNT_BIC
  , TRANS_RT
  , WON_GYULJE_AEK
  , WON_CHUI_AEK
) VALUES (
    #{corpGr}
  , TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
  , #{trCd}
  , #{fundCd}
  , #{trCoCd, jdbcType=VARCHAR}
  , #{trustee, jdbcType=VARCHAR}
  , #{yjCd}
  , NVL(#{bsType}, 0)
  , #{trSeq}
  , #{currency, jdbcType=VARCHAR}
  , NVL(#{trJusu}, 0)
  , NVL(#{trDanga}, 0)
  , NVL(#{trTax}, 0)
  , NVL(#{trCost}, 0)
  , NVL(#{trAek}, 0)
  , TO_DATE(REPLACE(#{gyuljeYmd}, '-', ''), 'YYYYMMDD')
  , NVL(#{gyuljeAek}, 0)
  , #{gyuljeJmCd, jdbcType=VARCHAR}
  , #{countCost, jdbcType=VARCHAR}
  , #{secCode, jdbcType=VARCHAR}
  , #{settLocation, jdbcType=VARCHAR}
  , #{countBic, jdbcType=VARCHAR}
  , #{transRt, jdbcType=NUMERIC}
  , #{wonGyuljeAek, jdbcType=NUMERIC}
  , #{wonChuiAek, jdbcType=NUMERIC}
)

mapper.update:
UPDATE SYT0MG
   SET TR_CO_CD       = #{trCoCd, jdbcType=VARCHAR}
     , TRUSTEE        = #{trustee, jdbcType=VARCHAR}
     , JM_CD          = #{yjCd}
     , BS_TYPE        = NVL(#{bsType}, 0)
     , CURRENCY       = #{currency, jdbcType=VARCHAR}
     , TR_JUSU        = NVL(#{trJusu}, 0)
     , TR_DANGA       = NVL(#{trDanga}, 0)
     , TR_TAX         = NVL(#{trTax}, 0)
     , TR_COST        = NVL(#{trCost}, 0)
     , TR_AEK         = NVL(#{trAek}, 0)
     , GYULJE_YMD     = TO_DATE(REPLACE(#{gyuljeYmd}, '-', ''), 'YYYYMMDD')
     , GYULJE_AEK     = NVL(#{gyuljeAek}, 0)
     , GYULJE_JM_CD   = #{gyuljeJmCd, jdbcType=VARCHAR}
     , COUNT_COST     = #{countCost, jdbcType=VARCHAR}
     , SEC_CODE       = #{secCode, jdbcType=VARCHAR}
     , SETT_LOCATION  = #{settLocation, jdbcType=VARCHAR}
     , COUNT_BIC      = #{countBic, jdbcType=VARCHAR}
     , TRANS_RT       = #{transRt, jdbcType=NUMERIC}
     , WON_GYULJE_AEK = #{wonGyuljeAek, jdbcType=NUMERIC}
     , WON_CHUI_AEK   = #{wonChuiAek, jdbcType=NUMERIC}
 WHERE CORP_GR        = #{corpGr}
   AND TR_YMD         = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
   AND TR_CD          = #{trCd}
   AND FUND_CD        = #{fundCd}
   AND TR_SEQ         = #{trSeq}

mapper.delete:
DELETE FROM SYT0MG
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
   AND TR_CD   = #{trCd}
   AND FUND_CD = #{fundCd}
   AND TR_SEQ  = #{trSeq}
